        requires
            self.wf(),
            au.pred().args(self),
        ensures
            match out {
                Some(ret_au) => ret_au == au,
                None => au.resolves(),
            }
    {
        let tracked mut maybe_au = Some(au);
        let tracked mut auth_au: Option<GhostVarAuth<Option<FlipAU>>> = None;
        let res;

        open_atomic_invariant!(self.inv.borrow() => v => {
            let tracked (mut value_perm, mut pend_perm, mut auth, mut gv, mut proto) = v;
            res = self.pending.compare_exchange(Tracked(&mut pend_perm), 0, 1);

            proof {
                if res.is_ok() {
                    // Successfully transitioned from 0 to 1
                    // Move the protocol from Empty to Offering state
                    let tracked gva = proto.take_empty();
                    auth_au = Some(gva);
                    // Save the atomic update in the protocol state
                    let tracked au_saved = maybe_au.tracked_take();
                    proto = Offering(Tracked(au_saved));
                }
                v = (value_perm, pend_perm, auth, gv, proto);
            }
        });

        if res.is_err() {
            return Some(Tracked(maybe_au.tracked_take()));
        }

        // At this point, we know auth_au was set to Some in the atomic operation
        proof {
            assert(auth_au.is_some());
        }

        let res;

        open_atomic_invariant!(self.inv.borrow() => v => {
            let tracked (mut value_perm, mut pend_perm, mut auth, mut gv, mut proto) = v;
            res = self.pending.compare_exchange(Tracked(&mut pend_perm), 1, 0);

            proof {
                if res.is_ok() {
                    // Successfully completed the handshake
                    // Flip the actual flag value
                    let old_value = value_perm.value();
                    let new_value = !old_value;

                    // The proper way to update according to the PAtomicBool interface
                    self.value.store(Tracked(&mut value_perm), new_value);

                    // Resolve the atomic update that was stored in the protocol state
                    let tracked offering_au = proto.take_offer();
                    try_open_atomic_update!(offering_au.get(), mut token => {
                        // Update the token's view to match the new value
                        auth.update(&mut token.value, new_value);
                        Tracked(Commit(token))
                    });

                    // Update protocol state to Accepted
                    proto = Accepted;
                }
                v = (value_perm, pend_perm, auth, gv, proto);
            }
        });

        if res.is_err() {
            open_atomic_invariant!(self.inv.borrow() => v => {
                let tracked (mut value_perm, mut pend_perm, mut auth, mut gv, mut proto) = v;
                self.pending.store(Tracked(&mut pend_perm), 0);

                proof {
                    // Cancel the handshake attempt
                    let tracked gva = auth_au.tracked_unwrap();
                    proto = Empty(gva);
                    v = (value_perm, pend_perm, auth, gv, proto);
                }
            });

            return None;
        }

        // If we get here, the handshake failed somewhere, so we should return the atomic update
        // But we already moved it into the protocol state, so we need to think carefully about logic

        // Actually, looking at the specification, when we return None, it means the AU was resolved
        // When we return Some(au), it means the AU should be tried again
        None
    }
